#!/usr/bin/env python3
"""
Logic and methodology analyzer for LaTeX/Typst papers.

Checks: paragraph-level coherence, method justification,
literature review quality (A1/A3), cross-section logic chain (C3).
"""

import argparse
import re
import sys
from pathlib import Path

try:
    from parsers import extract_abstract, get_parser
except ImportError:
    sys.path.append(str(Path(__file__).parent))
    from parsers import extract_abstract, get_parser


TRANSITIONS = {
    "addition": {"furthermore", "moreover", "in addition", "additionally"},
    "contrast": {"however", "nevertheless", "in contrast", "conversely"},
    "cause": {"therefore", "consequently", "as a result", "thus"},
}


def _has_transition(text: str) -> bool:
    lowered = text.lower()
    return any(token in lowered for values in TRANSITIONS.values() for token in values)


def _needs_method_justification(text: str) -> bool:
    lowered = text.lower()
    if "we use" not in lowered and "we adopt" not in lowered:
        return False
    return not any(marker in lowered for marker in ["because", "due to", "to ", "for "])


# ── Literature review quality checks (A1, A3) ──────────────────

AUTHOR_ENUM_EN = re.compile(
    r"^(?:In \d{4}|.*?\(\d{4}\).*?(?:proposed|introduced|presented|developed|designed)|"
    r".*[（(]\d{4}[)）].*(?:提出|设计|开发|构建))",
    re.IGNORECASE,
)

GAP_KEYWORDS_EN = re.compile(
    r"\b(gap|limitation|however.*(?:no|not|few)|remains|lack|overlooked|"
    r"under-explored|open problem|yet to be|inadequate|insufficient)\b|"
    r"(空白|不足|局限|仍未|缺乏|尚未解决|有待|研究较少)",
    re.IGNORECASE,
)


def _check_lit_review_enumeration(lines: list[str], start: int, end: int, parser) -> list[str]:
    """A1: Detect 3+ consecutive author/year enumeration patterns."""
    out: list[str] = []
    consecutive = 0
    streak_start = 0
    comment_prefix = parser.get_comment_prefix()
    for line_no in range(start, min(end, len(lines)) + 1):
        raw = lines[line_no - 1].strip()
        if not raw or raw.startswith(comment_prefix):
            continue
        visible = parser.extract_visible_text(raw)
        if not visible:
            continue
        if AUTHOR_ENUM_EN.search(visible):
            if consecutive == 0:
                streak_start = line_no
            consecutive += 1
        else:
            if consecutive >= 3:
                out.extend(
                    [
                        f"// LIT-REVIEW (Lines {streak_start}-{line_no - 1}) "
                        "[Severity: Major] [Priority: P1]: "
                        f"Author/year enumeration detected ({consecutive} consecutive entries)",
                        "// Suggested: Reorganize by theme clusters with critical analysis.",
                        "// Rationale: Chronological/author enumeration weakens literature synthesis.",
                        "",
                    ]
                )
            consecutive = 0
    if consecutive >= 3:
        out.extend(
            [
                f"// LIT-REVIEW (Lines {streak_start}-{min(end, len(lines))}) "
                "[Severity: Major] [Priority: P1]: "
                f"Author/year enumeration detected ({consecutive} consecutive entries)",
                "// Suggested: Reorganize by theme clusters with critical analysis.",
                "// Rationale: Chronological/author enumeration weakens literature synthesis.",
                "",
            ]
        )
    return out


def _check_gap_derivation(lines: list[str], start: int, end: int, parser) -> list[str]:
    """A3: Check last 10 lines of Related Work for research gap language."""
    out: list[str] = []
    scan_start = max(start, end - 10)
    comment_prefix = parser.get_comment_prefix()
    found_gap = False
    for line_no in range(scan_start, min(end, len(lines)) + 1):
        raw = lines[line_no - 1].strip()
        if not raw or raw.startswith(comment_prefix):
            continue
        visible = parser.extract_visible_text(raw)
        if visible and GAP_KEYWORDS_EN.search(visible):
            found_gap = True
            break
    if not found_gap:
        out.extend(
            [
                f"// LIT-REVIEW (Lines {scan_start}-{end}) "
                "[Severity: Major] [Priority: P1]: "
                "No research gap derivation found at end of Related Work",
                "// Suggested: Add explicit gap statement connecting literature to your contribution.",
                "// Rationale: Related Work should conclude by identifying gaps.",
                "",
            ]
        )
    return out


# ── Cross-section logic chain closure (C3) ──────────────────────

CONTRIBUTION_KEYWORDS_EN = re.compile(
    r"\b(we propose|we present|we introduce|our contribution|we design|we develop|"
    r"this paper proposes|this work presents|main contributions)\b|"
    r"(本文提出|本文设计|主要贡献|本研究提出)",
    re.IGNORECASE,
)
ANSWER_KEYWORDS_EN = re.compile(
    r"\b(we have shown|we demonstrated|results show|results demonstrate|"
    r"experiments confirm|we have proposed|this paper has presented|"
    r"our experiments show|findings indicate|we have addressed)\b|"
    r"(实验表明|结果表明|研究发现|本文证明了|验证了)",
    re.IGNORECASE,
)

INTRO_BACKGROUND_RE = re.compile(
    r"\b(important|growing|widely used|demand|need|application|applications|"
    r"real-world|industry|practical|in recent years|increasingly)\b|"
    r"(近年来|需求|背景|应用|现实场景|工业界|学术界)",
    re.IGNORECASE,
)
INTRO_PROBLEM_RE = re.compile(
    r"\b(problem|challenge|bottleneck|limitation|difficult|difficulty|issue|"
    r"expensive|costly|fails?|cannot|struggle|insufficient|inefficient)\b|"
    r"(问题|挑战|瓶颈|局限|困难|代价高|不足|低效)",
    re.IGNORECASE,
)
INTRO_PRIOR_RE = re.compile(
    r"\b(existing|previous|prior|earlier|current|traditional|state-of-the-art|"
    r"studies|literature|methods|approaches|however|nevertheless|recent work)\b|"
    r"(现有|已有|既有|先前|传统|文献|相关工作|已有研究|然而|但是)",
    re.IGNORECASE,
)
TRIAD_PROBLEM_RE = re.compile(
    r"\b(problem|challenge|task|goal|objective|bottleneck|limitation|address)\b|"
    r"(问题|挑战|任务|目标|瓶颈|局限|研究问题)",
    re.IGNORECASE,
)
TRIAD_METHOD_RE = re.compile(
    r"\b(propose|present|introduce|design|develop|framework|method|approach|"
    r"model|mechanism|pipeline|strategy)\b|"
    r"(提出|设计|构建|方法|框架|模型|机制|策略)",
    re.IGNORECASE,
)
TRIAD_RESULT_RE = re.compile(
    r"\b(result|results|improve|improvement|achieve|achieves|outperform|gain|"
    r"accuracy|f1|mae|mse|latency|throughput|benchmark|experiments show)\b|"
    r"(结果表明|实验表明|提升|优于|准确率|召回率|性能|基准)",
    re.IGNORECASE,
)
TRIAD_CONTRIBUTION_RE = re.compile(
    r"\b(contribution|contributions|novel|we propose|we present|we introduce|"
    r"main contributions)\b|"
    r"(贡献|创新点|本文提出|主要贡献|新颖)",
    re.IGNORECASE,
)


def _section_visible_lines(
    lines: list[str], bounds: tuple[int, int], parser
) -> list[tuple[int, str]]:
    visible_lines: list[tuple[int, str]] = []
    comment_prefix = parser.get_comment_prefix()
    start, end = bounds
    for line_no in range(start, min(end, len(lines)) + 1):
        raw = lines[line_no - 1].strip()
        if not raw or raw.startswith(comment_prefix):
            continue
        visible = parser.extract_visible_text(raw)
        if visible:
            visible_lines.append((line_no, visible))
    return visible_lines


def _coverage_map(text: str) -> dict[str, bool]:
    return {
        "problem": bool(TRIAD_PROBLEM_RE.search(text)),
        "method": bool(TRIAD_METHOD_RE.search(text)),
        "result": bool(TRIAD_RESULT_RE.search(text) or re.search(r"\d+(?:\.\d+)?%?", text)),
        "contribution": bool(TRIAD_CONTRIBUTION_RE.search(text)),
    }


def _check_introduction_funnel(
    lines: list[str], sections: dict[str, tuple[int, int]], parser
) -> list[str]:
    out: list[str] = []
    if "introduction" not in sections:
        return out

    visible_lines = _section_visible_lines(lines, sections["introduction"], parser)
    if len(visible_lines) < 3:
        return out

    first_problem = first_prior = first_contribution = None
    for line_no, visible in visible_lines:
        if first_problem is None and INTRO_PROBLEM_RE.search(visible):
            first_problem = line_no
        if first_prior is None and (INTRO_PRIOR_RE.search(visible) or "@" in lines[line_no - 1]):
            first_prior = line_no
        if first_contribution is None and CONTRIBUTION_KEYWORDS_EN.search(visible):
            first_contribution = line_no

    if first_contribution is None:
        return out

    if first_problem is None or first_contribution < first_problem:
        out.extend(
            [
                f"// INTRODUCTION (Line {first_contribution}) [Severity: Major] [Priority: P1]: "
                "Introduction may jump from background directly to contribution.",
                "// Suggested: Insert the unresolved bottleneck before presenting the method.",
                "// Rationale: The solution should be introduced only after the reader sees the problem.",
                "",
            ]
        )

    if first_problem is not None and first_prior is None:
        out.extend(
            [
                f"// INTRODUCTION (Line {first_problem}) [Severity: Major] [Priority: P1]: "
                "Introduction states the problem but does not derive it from prior-work limitations.",
                "// Suggested: Add literature-based insufficiencies before the contribution claim.",
                "// Rationale: This preserves the background -> bottleneck -> prior effort -> contribution funnel.",
                "",
            ]
        )
    elif (
        first_problem is not None
        and first_prior is not None
        and first_contribution is not None
        and first_prior > first_contribution
    ):
        out.extend(
            [
                f"// INTRODUCTION (Line {first_contribution}) [Severity: Major] [Priority: P1]: "
                "Contribution claim appears before prior-work insufficiencies are established.",
                "// Suggested: Reorder the introduction so prior-work limitations appear before the paper contribution.",
                "// Rationale: The introduction should unfold like a funnel instead of skipping steps.",
                "",
            ]
        )
    return out


def _check_tri_section_alignment(
    content: str, lines: list[str], sections: dict[str, tuple[int, int]], parser
) -> list[str]:
    out: list[str] = []
    if "introduction" not in sections or "conclusion" not in sections:
        return out

    abstract_text = extract_abstract(content)
    if not abstract_text:
        return out

    intro_text = " ".join(
        text for _, text in _section_visible_lines(lines, sections["introduction"], parser)
    )
    conclusion_text = " ".join(
        text for _, text in _section_visible_lines(lines, sections["conclusion"], parser)
    )
    if not intro_text or not conclusion_text:
        return out

    coverage = {
        "abstract": _coverage_map(abstract_text),
        "contribution_source": _coverage_map(intro_text),
        "conclusion": _coverage_map(conclusion_text),
    }
    required_facets = {
        facet
        for facet in ("problem", "method", "result", "contribution")
        if sum(1 for sec in coverage.values() if sec[facet]) >= 2
    }
    mismatches = []
    for section_name, section_coverage in coverage.items():
        missing = sorted(facet for facet in required_facets if not section_coverage[facet])
        if len(missing) >= 2 or (
            section_name in {"abstract", "conclusion"}
            and ("result" in missing or "contribution" in missing)
        ):
            mismatches.append(f"{section_name} missing {', '.join(missing)}")

    if coverage["contribution_source"]["contribution"]:
        if not coverage["abstract"]["contribution"]:
            mismatches.append("abstract missing contribution claim")
        if not coverage["conclusion"]["contribution"]:
            mismatches.append("conclusion missing contribution response")
    if coverage["abstract"]["method"] and not coverage["conclusion"]["result"]:
        mismatches.append("conclusion missing result evidence")

    if mismatches:
        out.extend(
            [
                "// LOGIC [Severity: Major] [Priority: P1]: "
                "Abstract, contribution claims, and conclusion may be misaligned.",
                f"// Observation: {'; '.join(mismatches)}.",
                "// Suggested: Align the problem, method, key results, and contribution across all three sections.",
                "// Rationale: These sections should summarize the same core story, not drift apart.",
                "",
            ]
        )
    return out


def _check_cross_section_closure(
    lines: list[str], sections: dict[str, tuple[int, int]], parser
) -> list[str]:
    """C3: Verify that intro contributions are answered in conclusion."""
    out: list[str] = []
    if "introduction" not in sections or "conclusion" not in sections:
        return out

    intro_start, intro_end = sections["introduction"]
    concl_start, concl_end = sections["conclusion"]
    comment_prefix = parser.get_comment_prefix()

    intro_claims = 0
    for line_no in range(intro_start, min(intro_end, len(lines)) + 1):
        raw = lines[line_no - 1].strip()
        if not raw or raw.startswith(comment_prefix):
            continue
        visible = parser.extract_visible_text(raw)
        if visible and CONTRIBUTION_KEYWORDS_EN.search(visible):
            intro_claims += 1

    if intro_claims == 0:
        return out

    concl_answers = 0
    for line_no in range(concl_start, min(concl_end, len(lines)) + 1):
        raw = lines[line_no - 1].strip()
        if not raw or raw.startswith(comment_prefix):
            continue
        visible = parser.extract_visible_text(raw)
        if visible and ANSWER_KEYWORDS_EN.search(visible):
            concl_answers += 1

    if concl_answers == 0:
        out.extend(
            [
                f"// LOGIC (Lines {concl_start}-{concl_end}) "
                "[Severity: Major] [Priority: P1]: "
                "[Script] Cross-section logic chain may be incomplete",
                f"// Observation: {intro_claims} contribution claim(s) in Introduction "
                "but no explicit answer language in Conclusion.",
                "// Suggested: Add statements that explicitly address each contribution.",
                "// Rationale: Conclusion should close the logic chain opened in Introduction.",
                "",
            ]
        )
    return out


def analyze(file_path: Path, section: str | None = None, cross_section: bool = False) -> list[str]:
    parser = get_parser(file_path)
    content = file_path.read_text(encoding="utf-8", errors="ignore")
    lines = content.split("\n")
    sections = parser.split_sections(content)

    if section:
        key = section.lower()
        if key not in sections:
            return [f"// ERROR [Severity: Critical] [Priority: P0]: Section not found: {section}"]
        ranges = [sections[key]]
    else:
        ranges = list(sections.values()) if sections else [(1, len(lines))]

    out: list[str] = []
    previous_visible = ""
    comment_prefix = parser.get_comment_prefix()
    for start, end in ranges:
        for line_no in range(start, min(end, len(lines)) + 1):
            raw = lines[line_no - 1].strip()
            if not raw or raw.startswith(comment_prefix):
                continue

            visible = parser.extract_visible_text(raw)
            if not visible:
                continue

            if _needs_method_justification(visible):
                out.extend(
                    [
                        f"// METHODOLOGY (Line {line_no}) [Severity: Major] [Priority: P1]: "
                        "Method choice lacks explicit justification",
                        f"// Current: {visible}",
                        "// Suggested: Add rationale (e.g., efficiency/accuracy/reproducibility).",
                        "// Rationale: Method statements should explain why the approach is selected.",
                        "",
                    ]
                )

            if (
                previous_visible
                and not _has_transition(visible)
                and re.search(
                    r"\b(problem|challenge|noisy|difficult)\b", previous_visible, re.IGNORECASE
                )
                and re.search(r"\b(we propose|we design|our method)\b", visible, re.IGNORECASE)
            ):
                out.extend(
                    [
                        f"// LOGIC (Line {line_no}) [Severity: Major] [Priority: P1]: "
                        "Potential logical jump between problem and solution",
                        f"// Current: {visible}",
                        "// Suggested: Add explicit transition (e.g., Therefore/Thus/To address this).",
                        "// Rationale: Strengthens paragraph-level coherence.",
                        "",
                    ]
                )

            previous_visible = visible

    # ── Section-level checks ───────────────────────────────────
    if sections:
        if not section and "introduction" in sections:
            out.extend(_check_introduction_funnel(lines, sections, parser))

        related_key = "related"
        if related_key in sections:
            r_start, r_end = sections[related_key]
            if not section or section.lower() == related_key:
                out.extend(_check_lit_review_enumeration(lines, r_start, r_end, parser))
                out.extend(_check_gap_derivation(lines, r_start, r_end, parser))

        if cross_section and not section:
            out.extend(_check_cross_section_closure(lines, sections, parser))
        if not section:
            out.extend(_check_tri_section_alignment(content, lines, sections, parser))

    if not out:
        out.append("// LOGIC/METHODOLOGY: No rule-based coherence issues detected.")
    return out


def main() -> int:
    cli = argparse.ArgumentParser(
        description="Logic and methodology analysis for LaTeX/Typst files"
    )
    cli.add_argument("file", type=Path, help="Target .tex/.typ file")
    cli.add_argument("--section", help="Section name to analyze")
    cli.add_argument(
        "--cross-section",
        action="store_true",
        help="Enable cross-section logic chain closure check",
    )
    args = cli.parse_args()

    if not args.file.exists():
        print(f"[ERROR] File not found: {args.file}", file=sys.stderr)
        return 1

    print("\n".join(analyze(args.file, args.section, args.cross_section)))
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""
Long sentence analyzer (MVP) for LaTeX/Typst papers.
"""

import argparse
import re
import sys
from pathlib import Path

try:
    from parsers import get_parser
except ImportError:
    sys.path.append(str(Path(__file__).parent))
    from parsers import get_parser


CLAUSE_MARKERS = {"which", "that", "because", "although", "while", "whereas", "if", "when"}


def _count_words(text: str) -> int:
    return len(re.findall(r"\b[\w'-]+\b", text))


def _count_clauses(text: str) -> int:
    lowered = text.lower()
    marker_hits = sum(1 for marker in CLAUSE_MARKERS if re.search(rf"\b{marker}\b", lowered))
    comma_parts = max(0, text.count(","))
    return marker_hits + comma_parts


def _simplify_sentence(text: str) -> str:
    parts = [p.strip() for p in text.split(",") if p.strip()]
    if len(parts) <= 1:
        return text
    head = parts[0]
    tail = ". ".join(parts[1:])
    return f"{head}. {tail}."


def analyze(file_path: Path, section: str | None, max_words: int, max_clauses: int) -> list[str]:
    parser = get_parser(file_path)
    content = file_path.read_text(encoding="utf-8", errors="ignore")
    lines = content.split("\n")
    sections = parser.split_sections(content)

    if section:
        key = section.lower()
        if key not in sections:
            return [f"% ERROR [Severity: Critical] [Priority: P0]: Section not found: {section}"]
        ranges = [sections[key]]
    else:
        ranges = list(sections.values()) if sections else [(1, len(lines))]

    output: list[str] = []
    for start, end in ranges:
        for line_no in range(start, min(end, len(lines)) + 1):
            raw = lines[line_no - 1].strip()
            if not raw or raw.startswith(parser.get_comment_prefix()):
                continue
            visible = parser.extract_visible_text(raw)
            if not visible:
                continue
            for sentence in re.split(r"(?<=[.!?])\s+", visible):
                sent = sentence.strip()
                if not sent:
                    continue
                words = _count_words(sent)
                clauses = _count_clauses(sent)
                if words <= max_words and clauses <= max_clauses:
                    continue

                simplified = _simplify_sentence(sent)
                output.extend(
                    [
                        f"% LONG SENTENCE (Line {line_no}, {words} words, {clauses} clauses) "
                        "[Severity: Minor] [Priority: P2]",
                        f"% Original: {sent}",
                        f"% Suggested: {simplified}",
                        "% Rationale: Sentence exceeds complexity threshold, split for readability.",
                        "",
                    ]
                )
    if not output:
        output.append("% LONG SENTENCE: No sentences exceeded configured thresholds.")
    return output


def main() -> int:
    cli = argparse.ArgumentParser(description="Long sentence analysis for LaTeX/Typst files (MVP)")
    cli.add_argument("file", type=Path, help="Target .tex/.typ file")
    cli.add_argument("--section", help="Section name to analyze")
    cli.add_argument("--max-words", type=int, default=50, help="Max words per sentence")
    cli.add_argument("--max-clauses", type=int, default=3, help="Max clauses per sentence")
    args = cli.parse_args()

    if not args.file.exists():
        print(f"[ERROR] File not found: {args.file}", file=sys.stderr)
        return 1

    print("\n".join(analyze(args.file, args.section, args.max_words, args.max_clauses)))
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""
IEEE-aware pseudocode checker for Typst paper projects.

Usage:
    uv run python -B check_pseudocode.py main.typ
    uv run python -B check_pseudocode.py main.typ --venue ieee
    uv run python -B check_pseudocode.py main.typ --json
"""

from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path

COMMENT_PREFIX = "//"
CAPTION_RE = re.compile(r"caption\s*:\s*\[")
FIGURE_RE = re.compile(r"#figure\s*\(")
ALGORITHM_FIGURE_RE = re.compile(r"#algorithm-figure\s*\(")
ALGORITHMIC_IMPORT_RE = re.compile(r'@preview/algorithmic(?::[^"]+)?')
LOVELACE_IMPORT_RE = re.compile(r'@preview/lovelace(?::[^"]+)?')
STYLE_ALGORITHM_RE = re.compile(r"style-algorithm")
LINE_NUMBER_RE = re.compile(r"(?:line[- ]?numbers?|numbering)\s*:\s*true|line[- ]?numbers?")


class PseudocodeChecker:
    """Check Typst pseudocode blocks for IEEE-like output quality."""

    def __init__(self, typ_file: str, venue: str = "") -> None:
        self.typ_file = Path(typ_file).resolve()
        self.venue = venue.lower().strip()
        self.content = self.typ_file.read_text(encoding="utf-8")
        self.lines = self.content.splitlines()
        self.issues: list[dict] = []

    def _add_issue(self, line: int | None, severity: str, priority: str, message: str) -> None:
        self.issues.append(
            {
                "module": "PSEUDOCODE",
                "line": line,
                "severity": severity,
                "priority": priority,
                "message": message,
            }
        )

    def _line_for_token(self, token: str) -> int | None:
        for lineno, line in enumerate(self.lines, start=1):
            if token in line:
                return lineno
        return None

    def _find_parenthesized_blocks(self, pattern: re.Pattern[str]) -> list[tuple[int, int, str]]:
        blocks: list[tuple[int, int, str]] = []
        for match in pattern.finditer(self.content):
            open_idx = match.end() - 1
            depth = 0
            end_idx = open_idx
            for index in range(open_idx, len(self.content)):
                char = self.content[index]
                if char == "(":
                    depth += 1
                elif char == ")":
                    depth -= 1
                    if depth == 0:
                        end_idx = index
                        break
            start_line = self.content[: match.start()].count("\n") + 1
            end_line = self.content[:end_idx].count("\n") + 1
            blocks.append((start_line, end_line, self.content[match.start() : end_idx + 1]))
        return blocks

    def _word_count(self, text: str) -> int:
        return len(re.findall(r"[A-Za-z0-9_\-\u4e00-\u9fff]+", text))

    def check_algorithmic_blocks(self) -> None:
        uses_algorithmic = bool(ALGORITHMIC_IMPORT_RE.search(self.content)) or bool(
            ALGORITHM_FIGURE_RE.search(self.content)
        )
        if not uses_algorithmic:
            return

        if not STYLE_ALGORITHM_RE.search(self.content):
            self._add_issue(
                self._line_for_token("style-algorithm"),
                "Major",
                "P1",
                "algorithmic blocks were detected without style-algorithm. IEEE-like output is more "
                "stable when the package styling hook is applied explicitly.",
            )

        for start_line, _end_line, text in self._find_parenthesized_blocks(ALGORITHM_FIGURE_RE):
            if CAPTION_RE.search(text) is None:
                self._add_issue(
                    start_line,
                    "Major",
                    "P1",
                    "algorithm-figure is missing a caption. IEEE-like pseudocode should use a figure "
                    "caption so the block can be referenced consistently.",
                )
            if LINE_NUMBER_RE.search(text) is None:
                self._add_issue(
                    start_line,
                    "Minor",
                    "P2",
                    "Line numbers were not detected in algorithm-figure. They are recommended for "
                    "IEEE-like review but not required.",
                )

            for local_line, raw_line in enumerate(text.splitlines(), start=start_line):
                stripped = raw_line.strip()
                if "comment(" not in stripped and "//" not in stripped:
                    continue
                payload = stripped.split("comment(", 1)[-1].rstrip(")")
                if "//" in stripped:
                    payload = stripped.split("//", 1)[-1]
                if self._word_count(payload) > 16:
                    self._add_issue(
                        local_line,
                        "Minor",
                        "P2",
                        "A pseudocode comment is unusually long. Keep comments short and move "
                        "paragraph-level explanation back into the main text.",
                    )
                    break

    def check_lovelace_blocks(self) -> None:
        if not LOVELACE_IMPORT_RE.search(self.content):
            return

        has_wrapper = bool(
            FIGURE_RE.search(self.content) or ALGORITHM_FIGURE_RE.search(self.content)
        )
        if self.venue == "ieee" and not has_wrapper:
            self._add_issue(
                self._line_for_token("lovelace"),
                "Critical",
                "P0",
                "lovelace output is not wrapped in a figure-like container. IEEE-like submissions "
                "should wrap free-form pseudocode in #figure(...) with a caption.",
            )

        if has_wrapper and CAPTION_RE.search(self.content) is None:
            self._add_issue(
                self._line_for_token("lovelace"),
                "Major",
                "P1",
                "A lovelace-based pseudocode block appears to be wrapped without a caption. Add a "
                "caption for IEEE-like figure handling.",
            )

    def check_prose_length(self) -> None:
        figure_blocks = self._find_parenthesized_blocks(
            FIGURE_RE
        ) + self._find_parenthesized_blocks(ALGORITHM_FIGURE_RE)
        for start_line, _end_line, text in figure_blocks:
            if "algorithm" not in text.lower() and "lovelace" not in self.content.lower():
                continue
            for local_line, raw_line in enumerate(text.splitlines(), start=start_line):
                stripped = raw_line.strip()
                if not stripped or stripped.startswith("//") or "caption:" in stripped:
                    continue
                if self._word_count(stripped) > 24:
                    self._add_issue(
                        local_line,
                        "Minor",
                        "P2",
                        "A pseudocode line contains prose-length explanation. Prefer short algorithmic "
                        "steps and move long explanation into the surrounding paragraph.",
                    )
                    return

    def check(self) -> list[dict]:
        self.issues = []
        self.check_algorithmic_blocks()
        self.check_lovelace_blocks()
        self.check_prose_length()
        return sorted(self.issues, key=lambda item: (item.get("line") or 0, item["severity"]))

    def generate_report(self, issues: list[dict]) -> str:
        if not issues:
            return ""
        lines = []
        for issue in issues:
            line_part = f"(Line {issue['line']}) " if issue.get("line") else ""
            lines.append(
                f"{COMMENT_PREFIX} PSEUDOCODE {line_part}[Severity: {issue['severity']}] "
                f"[Priority: {issue['priority']}]: {issue['message']}"
            )
        return "\n".join(lines)


def main() -> int:
    parser = argparse.ArgumentParser(description="IEEE-aware pseudocode checker for Typst papers")
    parser.add_argument("file", help="Source .typ file to check")
    parser.add_argument(
        "--venue",
        default="",
        choices=["", "ieee", "acm", "springer", "neurips", "cvpr"],
        help="Venue context used for stricter checks",
    )
    parser.add_argument("--json", action="store_true", help="Output JSON format")
    args = parser.parse_args()

    path = Path(args.file)
    if not path.exists():
        print(f"[ERROR] File not found: {args.file}", file=sys.stderr)
        return 1

    checker = PseudocodeChecker(str(path), venue=args.venue)
    issues = checker.check()

    if args.json:
        print(json.dumps(issues, indent=2, ensure_ascii=False))
    else:
        output = checker.generate_report(issues)
        if output:
            print(output)

    return 1 if any(issue["severity"] == "Critical" for issue in issues) else 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""
Table Structure Checker for Typst - Validate three-line table compliance.

Usage:
    uv run python -B check_tables.py main.typ
    uv run python -B check_tables.py main.typ --fix-suggestions
    uv run python -B check_tables.py main.typ --json
"""

import argparse
import json
import re
import sys
from pathlib import Path


class TableChecker:
    """Validate Typst tables against the three-line standard."""

    LEVEL_ERROR = "ERROR"
    LEVEL_WARNING = "WARNING"
    LEVEL_INFO = "INFO"

    def __init__(self, typ_file: str):
        self.typ_file = Path(typ_file).resolve()
        self.content = ""
        self.lines: list[str] = []
        self.issues: list[dict] = []

    def _load(self) -> bool:
        """Load the .typ file content."""
        if not self.typ_file.exists():
            self.issues.append(
                {
                    "line": 0,
                    "level": self.LEVEL_ERROR,
                    "priority": "P1",
                    "message": f"File not found: {self.typ_file}",
                    "category": "file",
                }
            )
            return False
        self.content = self.typ_file.read_text(encoding="utf-8", errors="replace")
        self.lines = self.content.split("\n")
        return True

    def check(self, fix_suggestions: bool = False) -> dict:
        """Run all table structure checks."""
        if not self._load():
            return self._result()

        tables = self._find_table_blocks()
        for table in tables:
            self._check_vertical_lines(table)
            self._check_hline_count(table)
            self._check_stroke_none(table)
            self._check_number_precision(table)

        if fix_suggestions:
            for issue in self.issues:
                issue["fix"] = self._suggest_fix(issue)

        return self._result()

    def _result(self) -> dict:
        if not self.issues:
            status = "PASS"
        elif any(i["level"] == self.LEVEL_ERROR for i in self.issues):
            status = "FAIL"
        else:
            status = "WARNING"

        return {
            "status": status,
            "file": str(self.typ_file),
            "table_count": len(self._find_table_blocks()),
            "issue_count": len(self.issues),
            "issues": self.issues,
        }

    def _find_table_blocks(self) -> list[dict]:
        """Find table() calls in the Typst source."""
        tables = []
        # Simple heuristic: find lines containing table( and track the block
        for i, line in enumerate(self.lines, 1):
            stripped = line.strip()
            # Skip comments
            if stripped.startswith("//"):
                continue
            if "table(" in stripped:
                # Find the extent of this table block
                block_lines = [line]
                depth = 0
                start = i
                for ch in stripped[stripped.index("table(") + 6 :]:
                    if ch == "(":
                        depth += 1
                    elif ch == ")":
                        if depth == 0:
                            break
                        depth -= 1

                # If not closed on same line, scan forward
                if depth >= 0 and stripped.count("(") > stripped.count(")"):
                    for j in range(i, min(i + 100, len(self.lines))):
                        block_lines.append(self.lines[j])
                        full = "\n".join(block_lines)
                        if full.count("(") <= full.count(")"):
                            break

                tables.append(
                    {
                        "start": start,
                        "end": start + len(block_lines) - 1,
                        "content": "\n".join(block_lines),
                    }
                )

        return tables

    def _check_vertical_lines(self, table: dict) -> None:
        """Check for table.vline() in the table."""
        content = table["content"]
        if "table.vline" in content:
            self.issues.append(
                {
                    "line": table["start"],
                    "level": self.LEVEL_ERROR,
                    "priority": "P1",
                    "message": "table.vline() detected. Three-line tables must not have vertical lines.",
                    "category": "vertical_lines",
                }
            )

    def _check_hline_count(self, table: dict) -> None:
        """Check for correct number of table.hline() calls."""
        content = table["content"]
        hline_count = len(re.findall(r"table\.hline", content))

        if hline_count == 0:
            self.issues.append(
                {
                    "line": table["start"],
                    "level": self.LEVEL_WARNING,
                    "priority": "P1",
                    "message": "No table.hline() found. A three-line table needs exactly 3 horizontal lines (top, mid, bottom).",
                    "category": "hline_missing",
                }
            )
        elif hline_count > 3:
            self.issues.append(
                {
                    "line": table["start"],
                    "level": self.LEVEL_WARNING,
                    "priority": "P2",
                    "message": f"Found {hline_count} table.hline() calls. A three-line table should have exactly 3.",
                    "category": "hline_excess",
                }
            )

    def _check_stroke_none(self, table: dict) -> None:
        """Check that the table has stroke: none to disable default borders."""
        content = table["content"]
        # Look for stroke: none in the table() call
        if "stroke:" in content and "stroke: none" not in content and "stroke:none" not in content:
            self.issues.append(
                {
                    "line": table["start"],
                    "level": self.LEVEL_WARNING,
                    "priority": "P1",
                    "message": "Table has a stroke setting but not 'stroke: none'. Set stroke: none and use table.hline() for three-line style.",
                    "category": "stroke",
                }
            )

    def _check_number_precision(self, table: dict) -> None:
        """Check for inconsistent decimal precision in table data."""
        content = table["content"]
        # Extract cell values: look for [number] patterns
        cells = re.findall(r"\[(\d+\.?\d*)\]", content)
        if len(cells) < 2:
            return

        decimals_seen: set[int] = set()
        for cell in cells:
            if "." in cell:
                decimals_seen.add(len(cell.split(".")[1]))

        if len(decimals_seen) > 1:
            self.issues.append(
                {
                    "line": table["start"],
                    "level": self.LEVEL_WARNING,
                    "priority": "P3",
                    "message": f"Inconsistent decimal precision: found {sorted(decimals_seen)} decimal places. Use consistent precision.",
                    "category": "precision",
                }
            )

    def _suggest_fix(self, issue: dict) -> str:
        cat = issue.get("category", "")
        if cat == "vertical_lines":
            return "Remove all table.vline() calls."
        if cat == "hline_missing":
            return "Add table.hline(stroke: 0.8pt) at top and bottom, table.hline(stroke: 0.5pt) after headers."
        if cat == "hline_excess":
            return "Keep only 3 table.hline() calls: top, after header, and bottom."
        if cat == "stroke":
            return "Set stroke: none on the table() call."
        if cat == "precision":
            return "Align all values to the same number of decimal places."
        return ""

    def generate_report(self, result: dict) -> str:
        lines = []
        lines.append("=" * 60)
        lines.append("Table Structure Check Report (Typst)")
        lines.append("=" * 60)
        lines.append(f"File: {result['file']}")
        lines.append(f"Tables found: {result['table_count']}")
        lines.append(f"Status: {result['status']}")
        lines.append(f"Issues: {result['issue_count']}")

        if result["issues"]:
            lines.append("")
            lines.append("-" * 60)

            by_category: dict[str, list[dict]] = {}
            for issue in result["issues"]:
                cat = issue.get("category", "other")
                if cat not in by_category:
                    by_category[cat] = []
                by_category[cat].append(issue)

            for category, issues in sorted(by_category.items()):
                lines.append(f"\n[{category.upper()}] ({len(issues)} issues)")
                for issue in issues:
                    prefix = f"  Line {issue['line']}" if issue["line"] else "  Global"
                    lines.append(f"{prefix}: [{issue['level']}] {issue['message']}")
                    if issue.get("fix"):
                        lines.append(f"    Fix: {issue['fix']}")

        lines.append("")
        lines.append("=" * 60)
        return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(
        description="Table Structure Checker (Typst) - three-line table compliance"
    )
    parser.add_argument("typ_file", help=".typ file to check")
    parser.add_argument(
        "--fix-suggestions", "-f", action="store_true", help="Include fix suggestions"
    )
    parser.add_argument("--json", "-j", action="store_true", help="Output in JSON format")

    args = parser.parse_args()

    if not Path(args.typ_file).exists():
        print(f"[ERROR] File not found: {args.typ_file}")
        sys.exit(1)

    checker = TableChecker(args.typ_file)
    result = checker.check(fix_suggestions=args.fix_suggestions)

    if args.json:
        print(json.dumps(result, indent=2))
    else:
        print(checker.generate_report(result))

    sys.exit(1 if result["status"] == "FAIL" else 0)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
Academic expression improver (MVP) for LaTeX/Typst papers.
"""

import argparse
import re
import sys
from pathlib import Path

try:
    from parsers import get_parser
except ImportError:
    sys.path.append(str(Path(__file__).parent))
    from parsers import get_parser


WEAK_VERBS = {
    r"\buse\b": "employ",
    r"\bget\b": "obtain",
    r"\bmake\b": "develop",
    r"\bshow\b": "demonstrate",
}

WEAK_PHRASES = {
    r"\bvery\b": "highly",
    r"\ba lot of\b": "many",
    r"\bkind of\b": "",
}


def _enhance(text: str) -> tuple[str, list[str]]:
    revised = text
    changes: list[str] = []
    for pattern, replacement in WEAK_VERBS.items():
        if re.search(pattern, revised, re.IGNORECASE):
            revised = re.sub(pattern, replacement, revised, flags=re.IGNORECASE)
            changes.append(f"Weak verb replaced: {pattern} -> {replacement}")
    for pattern, replacement in WEAK_PHRASES.items():
        if re.search(pattern, revised, re.IGNORECASE):
            revised = re.sub(pattern, replacement, revised, flags=re.IGNORECASE)
            changes.append(f"Weak phrase adjusted: {pattern} -> {replacement or '[deleted]'}")
    revised = re.sub(r"\s+", " ", revised).strip()
    return revised, changes


def analyze(file_path: Path, section: str | None) -> list[str]:
    parser = get_parser(file_path)
    content = file_path.read_text(encoding="utf-8", errors="ignore")
    lines = content.split("\n")
    sections = parser.split_sections(content)

    if section:
        key = section.lower()
        if key not in sections:
            return [f"% ERROR [Severity: Critical] [Priority: P0]: Section not found: {section}"]
        ranges = [sections[key]]
    else:
        ranges = list(sections.values()) if sections else [(1, len(lines))]

    out: list[str] = []
    for start, end in ranges:
        for line_no in range(start, min(end, len(lines)) + 1):
            raw = lines[line_no - 1].strip()
            if not raw or raw.startswith(parser.get_comment_prefix()):
                continue
            visible = parser.extract_visible_text(raw)
            if not visible:
                continue
            revised, changes = _enhance(visible)
            if revised.lower() == visible.lower() or not changes:
                continue
            out.extend(
                [
                    f"% EXPRESSION (Line {line_no}) [Severity: Minor] [Priority: P2]: Improve academic tone",
                    f"% Original: {visible}",
                    f"% Revised:  {revised}",
                    f"% Rationale: {'; '.join(changes)}",
                    "",
                ]
            )
    if not out:
        out.append("% EXPRESSION: No weak-expression patterns detected.")
    return out


def main() -> int:
    cli = argparse.ArgumentParser(
        description="Academic expression improvement for LaTeX/Typst files"
    )
    cli.add_argument("file", type=Path, help="Target .tex/.typ file")
    cli.add_argument("--section", help="Section name to analyze")
    args = cli.parse_args()

    if not args.file.exists():
        print(f"[ERROR] File not found: {args.file}", file=sys.stderr)
        return 1

    print("\n".join(analyze(args.file, args.section)))
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""
Document Parsers for Academic Writing Skills (Typst)
Support for Typst document parsing.
"""

import re
from abc import ABC, abstractmethod
from typing import Any


class DocumentParser(ABC):
    """Abstract base class for document parsers."""

    @abstractmethod
    def split_sections(self, content: str) -> dict[str, tuple[int, int]]:
        """
        Split document into sections.
        Returns map of {section_name: (start_line, end_line)}.
        """
        pass

    @abstractmethod
    def extract_visible_text(self, line: str) -> str:
        """
        Extract text visible to reader, preserving structure markers.
        Used for line-by-line AI trace checking.
        """
        pass

    @abstractmethod
    def clean_text(self, content: str, keep_structure: bool = False) -> str:
        """
        Extract pure prose text, removing all markup.
        Used for prose extraction and word counting.
        """
        pass

    @abstractmethod
    def get_comment_prefix(self) -> str:
        """Get the comment prefix for the language."""
        pass


class TypstParser(DocumentParser):
    """Parser for Typst documents."""

    # Section patterns (Heading 1-3)
    # Matches: = Introduction or == Related Work
    SECTION_PATTERNS = {
        "introduction": r"^=\s+(?:Introduction|INTRODUCTION|绪论|引言)",
        "related": r"^=\s+(?:Related\s+Work|RELATED\s+WORK|相关工作|文献综述)",
        "method": r"^=\s+.*(?:Method|Methodology|Approach|方法|原理|设计)",
        "experiment": r"^=\s+.*(?:Experiment|Evaluation|Implementation|实验|实现|测试)",
        "result": r"^=\s+.*(?:Result|Performance|结果|性能)",
        "discussion": r"^=\s+.*(?:Discussion|Analysis|讨论|分析)",
        "conclusion": r"^=\s+.*(?:Conclusion|Conclusions|结论|总结与展望)",
        "abstract": r"#abstract\[",
    }

    PRESERVE_PATTERNS = [
        r"@[a-zA-Z0-9_-]+",  # Citations @key
        r"#cite\([^)]+\)",  # Function calls #cite()
        r"#figure\([^)]+\)",  # Figures
        r"#table\([^)]+\)",  # Tables
        r"\$[^$]+\$",  # Math $...$
        r"//.*",  # Line comments
        r"/\*.*?\*/",  # Block comments
        r"<[a-zA-Z0-9_-]+>",  # Labels <label>
        r"#link\([^)]+\)",  # Links
    ]

    def get_comment_prefix(self) -> str:
        return "//"

    def split_sections(self, content: str) -> dict[str, tuple[int, int]]:
        lines = content.split("\n")
        sections = {}
        current_section = "preamble"
        start_line = 0

        for i, line in enumerate(lines, 1):
            line = line.strip()
            # Ignore comments
            if line.startswith("//"):
                continue

            for section_name, pattern in self.SECTION_PATTERNS.items():
                if re.search(pattern, line, re.IGNORECASE):
                    if current_section != "preamble":
                        sections[current_section] = (start_line, i - 1)
                    current_section = section_name
                    start_line = i
                    break

        if current_section != "preamble":
            sections[current_section] = (start_line, len(lines))

        return sections

    def extract_visible_text(self, line: str) -> str:
        # Same logic as LatexParser but with Typst patterns
        temp_line = line

        # Remove comments first for Typst
        if "//" in temp_line:
            temp_line = temp_line.split("//")[0]

        preserved = []
        for pattern in self.PRESERVE_PATTERNS:
            matches = list(re.finditer(pattern, temp_line, re.DOTALL))
            for match in reversed(matches):
                preserved.append(
                    {"start": match.start(), "end": match.end(), "text": match.group()}
                )
                placeholder = " " * (match.end() - match.start())
                temp_line = temp_line[: match.start()] + placeholder + temp_line[match.end() :]

        preserved.sort(key=lambda x: x["start"])

        visible_parts = []
        last_end = 0
        for item in preserved:
            if item["start"] > last_end:
                visible_parts.append(temp_line[last_end : item["start"]])
            last_end = item["end"]
        if last_end < len(temp_line):
            visible_parts.append(temp_line[last_end:])

        return " ".join(visible_parts).strip()

    def clean_text(self, content: str, keep_structure: bool = False) -> str:
        # Remove comments
        content = re.sub(r"//.*", "", content)
        content = re.sub(r"/\*.*?\*/", "", content, flags=re.DOTALL)

        # Remove math
        content = re.sub(r"\$[^$]+\$", "", content)

        # Handle headers
        if keep_structure:
            content = re.sub(r"^=+\s+(.+)$", r"\n\n## \1\n\n", content, flags=re.MULTILINE)
        else:
            content = re.sub(r"^=+\s+.+$", "", content, flags=re.MULTILINE)

        # Remove function calls #func(...) - basic support
        content = re.sub(r"#[a-zA-Z0-9_]+\([^)]*\)", "", content)
        content = re.sub(r"@[a-zA-Z0-9_-]+", "", content)
        content = re.sub(r"<[a-zA-Z0-9_-]+>", "", content)

        # Cleanup
        content = re.sub(r"\n+", "\n", content)
        content = re.sub(r" +", " ", content)
        content = re.sub(r"\.(\s*\.)+", ".", content)  # Fix multiple periods
        return content.strip()


def get_parser(file_path: Any) -> DocumentParser:
    """Factory method to get appropriate parser for Typst files."""
    return TypstParser()


def _normalize_whitespace(text: str) -> str:
    return re.sub(r"\s+", " ", text).strip()


def _extract_balanced_block(content: str, start_idx: int, opener: str, closer: str) -> str:
    """Extract a balanced block body from content starting at opener index."""
    if start_idx < 0 or start_idx >= len(content) or content[start_idx] != opener:
        return ""

    depth = 0
    block_start = -1

    for i in range(start_idx, len(content)):
        char = content[i]
        if char == opener:
            depth += 1
            if depth == 1:
                block_start = i + 1
        elif char == closer:
            depth -= 1
            if depth == 0 and block_start >= 0:
                return content[block_start:i]
            if depth < 0:
                return ""
    return ""


def _strip_typst_markup(text: str) -> str:
    """Strip lightweight Typst markup for title/abstract extraction."""
    cleaned = text
    cleaned = re.sub(r"#\w+\([^)]*\)", " ", cleaned)

    # Collapse simple bracket macros repeatedly (e.g., #emph[Paper], nested forms).
    while True:
        collapsed = re.sub(r"#\w+\[([^\[\]]*)\]", r"\1", cleaned)
        if collapsed == cleaned:
            break
        cleaned = collapsed

    cleaned = re.sub(r"[\[\]]", " ", cleaned)
    return _normalize_whitespace(cleaned)


def extract_title(content: str) -> str:
    """Extract document title from Typst source content."""
    # Typst common: #set document(title: "...")
    typst_str = re.search(
        r"#set\s+document\s*\(\s*title\s*:\s*\"([^\"]+)\"",
        content,
        re.DOTALL,
    )
    if typst_str:
        return _normalize_whitespace(typst_str.group(1))

    # Typst bracket style: #set document(title: [ ... ])
    typst_block = re.search(r"#set\s+document\s*\(\s*title\s*:\s*\[", content, re.DOTALL)
    if typst_block:
        bracket_idx = typst_block.end() - 1
        text = _extract_balanced_block(content, bracket_idx, "[", "]")
        if text:
            return _strip_typst_markup(text)

    return ""


def extract_abstract(content: str) -> str:
    """Extract abstract text from Typst source content."""
    # Typst: #abstract[...]
    typst_abs = re.search(r"#abstract\[", content, re.DOTALL)
    if typst_abs:
        bracket_idx = typst_abs.end() - 1
        text = _extract_balanced_block(content, bracket_idx, "[", "]")
        if text:
            return _strip_typst_markup(text)

    heading_abs = re.search(
        r"^=\s+摘要\s*\n(.*?)(?=^=\s+|\Z)",
        content,
        re.DOTALL | re.MULTILINE,
    )
    if heading_abs:
        return _strip_typst_markup(heading_abs.group(1))

    return ""

#!/usr/bin/env python3
"""
Chinese -> English academic translation helper (MVP).

This script is terminology-driven and provides:
1) terminology confirmation table
2) draft translation
3) ambiguity notes requiring manual confirmation
"""

import argparse
import sys
from pathlib import Path

TERMINOLOGY = {
    "deep-learning": {
        "注意力机制": "attention mechanism",
        "损失函数": "loss function",
        "神经网络": "neural network",
        "时间序列预测": "time series forecasting",
        "模型": "model",
    },
    "time-series": {
        "时间序列": "time series",
        "预测": "forecasting",
        "滑动窗口": "sliding window",
        "趋势": "trend",
        "季节性": "seasonality",
    },
    "industrial-control": {
        "故障检测": "fault detection",
        "工业控制": "industrial control",
        "控制系统": "control system",
        "实时": "real-time",
        "鲁棒性": "robustness",
    },
}

AMBIGUOUS_TERMS = {
    "控制": ["control", "controller", "regulation"],
    "性能": ["performance", "efficiency"],
    "优化": ["optimization", "improvement"],
}

COMMON_PATTERNS = {
    "本文提出": "We propose",
    "实验结果表明": "Experimental results demonstrate that",
    "与...相比": "Compared with ...",
    "在...中": "in ...",
}


def _load_source(input_arg: str) -> str:
    path = Path(input_arg)
    if path.exists() and path.is_file():
        return path.read_text(encoding="utf-8", errors="ignore")
    return input_arg


def _build_term_table(text: str, domain: str) -> list[tuple[str, str, str]]:
    table: list[tuple[str, str, str]] = []
    domain_terms = TERMINOLOGY.get(domain, {})
    for zh, en in domain_terms.items():
        if zh in text:
            table.append((zh, en, domain))
    return table


def _draft_translate(text: str, domain: str) -> tuple[str, list[str]]:
    translated = text
    notes: list[str] = []

    for zh, en in TERMINOLOGY.get(domain, {}).items():
        if zh in translated:
            translated = translated.replace(zh, en)

    for zh, en in COMMON_PATTERNS.items():
        if zh in translated:
            translated = translated.replace(zh, en)

    for term, options in AMBIGUOUS_TERMS.items():
        if term in translated:
            notes.append(f"Ambiguous term '{term}' -> choose one: {', '.join(options)}")

    # Minimal sentence formatting
    translated = translated.replace("。", ". ").replace("，", ", ")
    translated = " ".join(translated.split())
    return translated, notes


def translate(input_arg: str, domain: str) -> str:
    text = _load_source(input_arg)
    table = _build_term_table(text, domain)
    draft, notes = _draft_translate(text, domain)

    lines: list[str] = []
    lines.append("### Terminology Confirmation")
    lines.append("| 中文 | English | Domain |")
    lines.append("|------|---------|--------|")
    if table:
        for zh, en, dom in table:
            lines.append(f"| {zh} | {en} | {dom} |")
    else:
        lines.append("| (none detected) | - | - |")

    lines.append("\n### Translation Draft")
    lines.append(f"% ORIGINAL: {text}")
    lines.append(f"% TRANSLATION: {draft}")

    lines.append("\n### Notes")
    if notes:
        for note in notes:
            lines.append(f"- ⚠️ [PENDING CONFIRMATION] {note}")
    else:
        lines.append("- No high-risk ambiguous terms detected by rule set.")

    return "\n".join(lines)


def main() -> int:
    cli = argparse.ArgumentParser(description="Terminology-driven academic translation helper")
    cli.add_argument("input", help="Chinese text or a file path containing Chinese text")
    cli.add_argument(
        "--domain",
        choices=["deep-learning", "time-series", "industrial-control"],
        default="deep-learning",
        help="Domain terminology set",
    )
    cli.add_argument("--output", help="Output file path")
    args = cli.parse_args()

    result = translate(args.input, args.domain)
    if args.output:
        Path(args.output).write_text(result, encoding="utf-8")
        print(f"[SUCCESS] Translation report written to: {args.output}")
    else:
        print(result)
    return 0


if __name__ == "__main__":
    sys.exit(main())
